<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {Plus,Refresh,Right,Document,Link,Search} from '@element-plus/icons-vue'
import {marked} from 'marked'
import DOMPurify from 'dompurify'
import {useWorkspace} from '../store'
import {api,get,post} from '../api'
const route=useRoute(),router=useRouter(),store=useWorkspace()
const page=computed(()=>route.params.id?'detail':String(route.params.page||'dashboard'))
const loading=ref(false),failed=ref(false),dash=ref<any>({}),tasks=ref<any[]>([]),changes=ref<any[]>([]),claims=ref<any[]>([]),reports=ref<any[]>([]),impacts=ref<any[]>([]),comparison=ref<any>({dimensions:[],claims:[],saved:[]})
const selectedReport=ref<any>(null),evidence=ref<any>(null),snapshot=ref<any>(null),drawer=ref(false),productDialog=ref(false),sourceDialog=ref(false),editing=ref<number|null>(null),query=ref(''),selection=ref<number[]>([]),relation=ref('insufficient_evidence')
const productForm=ref({name:'',company:'',category:'',description:'',official_url:''})
const sourceForm=ref({product_id:0,url:'',source_type:'official_website'})
const product=computed(()=>store.products.find(p=>p.id===Number(route.params.id)))
const visibleProducts=computed(()=>store.products.filter(p=>!query.value||p.name.toLowerCase().includes(query.value.toLowerCase())))
const detailSources=computed(()=>store.sources.filter(s=>s.product_id===product.value?.id))
const detailClaims=computed(()=>claims.value.filter(c=>c.product_id===product.value?.id))
const reportHtml=computed(()=>DOMPurify.sanitize(marked.parse(selectedReport.value?.markdown||'') as string))
const names=(id:number)=>store.products.find(p=>p.id===id)?.name||'产品 '+id
const labels:Record<string,string>={supported:'有公开支持证据',not_supported:'明确不支持',unknown:'未知',not_applicable:'不适用',verified:'原文已验证',unverified:'待核验',conflicting:'来源冲突',released:'已发布',demo:'演示',planned:'计划中',in_development:'开发中',pending:'尚未采集',success:'采集成功',error:'采集失败',queued:'排队中',running:'执行中',completed:'完成',partial:'部分失败',interrupted:'已中断',low:'低',medium:'中',high:'高',feature_added:'功能新增',feature_removed:'功能移除',feature_updated:'功能更新',pricing_changed:'定价变化',documentation_updated:'文档更新',release_published:'版本发布',other:'其他',direct_competition:'直接竞争',functional_overlap:'功能重叠',ecosystem_benchmark:'生态对标',not_comparable:'不可直接比较',insufficient_evidence:'证据不足'}
const label=(s:string)=>labels[s]||s
const date=(s:string)=>s?new Date(s).toLocaleString('zh-CN'):'—'
async function load(){loading.value=true;failed.value=false;try{await store.refresh();const result=await Promise.all(['/dashboard','/tasks','/changes?limit=200','/claims?limit=200','/reports','/comparisons','/impacts'].map(get));[dash.value,tasks.value,changes.value,claims.value,reports.value,comparison.value,impacts.value]=result;if(!selection.value.length)selection.value=store.products.filter(p=>p.is_active).map(p=>p.id)}catch{failed.value=true}finally{loading.value=false}}
async function run(id?:number){await post(id?`/sources/${id}/fetch`:'/research',{source_ids:[]});ElMessage.success('研究任务已提交');await load()}
function editProduct(p?:any){editing.value=p?.id||null;productForm.value=p?{name:p.name,company:p.company,category:p.category,description:p.description,official_url:p.official_url}:{name:'',company:'',category:'',description:'',official_url:''};productDialog.value=true}
async function saveProduct(){if(editing.value)await api.patch('/products/'+editing.value,productForm.value);else await post('/products',productForm.value);productDialog.value=false;await load()}
async function disable(p:any){await ElMessageBox.confirm('停用产品并停用其数据源？历史研究数据将保留。','停用产品');await api.delete('/products/'+p.id);await load()}
function addSource(pid?:number){editing.value=null;sourceForm.value={product_id:pid||store.products[0]?.id||0,url:'',source_type:'official_website'};sourceDialog.value=true}
function editSource(s:any){editing.value=s.id;sourceForm.value={product_id:s.product_id,url:s.url,source_type:s.source_type};sourceDialog.value=true}
async function saveSource(){if(editing.value)await api.patch('/sources/'+editing.value,{url:sourceForm.value.url,source_type:sourceForm.value.source_type});else await post('/sources',sourceForm.value);sourceDialog.value=false;await load()}
async function toggleSource(s:any){await api.patch('/sources/'+s.id,{is_active:!s.is_active});await load()}
async function showEvidence(c:any){evidence.value=c;snapshot.value=await get('/snapshots/'+c.snapshot_id);drawer.value=true}
async function showSnapshots(s:any){evidence.value=null;const rows=await get(`/sources/${s.id}/snapshots`);snapshot.value=rows.length?rows:null;drawer.value=true}
function cell(pid:number,dimension:string){return comparison.value.claims.filter((c:any)=>c.product_id===pid&&c.dimension===dimension)}
async function saveComparison(){await post('/comparisons',{product_ids:selection.value,relationship:relation.value});ElMessage.success('对比关系已保存');await load()}
async function generate(){selectedReport.value=await post('/reports',{title:'具身智能研发基础设施 · 竞品研究'});await load()}
function download(){const url=URL.createObjectURL(new Blob([selectedReport.value.markdown],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='InsightFlow-report.md';a.click();URL.revokeObjectURL(url)}
async function copy(){try{await navigator.clipboard.writeText(selectedReport.value.markdown);ElMessage.success('已复制')}catch{ElMessage.error('浏览器不允许访问剪贴板，请下载报告')}}
let timer:ReturnType<typeof setInterval>
onMounted(()=>{load();timer=setInterval(async()=>{try{if(tasks.value.some(t=>['running','queued'].includes(t.status)))await load()}catch{}},4000)})
onUnmounted(()=>clearInterval(timer));watch(()=>route.fullPath,load)
</script>
<template>
 <div v-loading="loading">
 <el-alert v-if="failed" title="加载失败，请检查后端服务并点击刷新" type="error" show-icon :closable="false"/>
 <div class="page-heading"><div><div class="eyebrow">INTELLIGENCE / {{page.toUpperCase()}}</div><h1>{{({dashboard:'研究总览',products:'产品与数据源',detail:product?.name||'产品详情',comparison:'竞品能力对比',timeline:'变化时间线',reports:'研究报告',tasks:'任务与设置'} as any)[page]}}</h1><p>从公开信息到产品洞察，每一步都有证据。</p></div><div class="actions"><el-button :icon="Refresh" @click="load">刷新</el-button><el-button v-if="page==='products'" type="primary" :icon="Plus" @click="editProduct()">添加产品</el-button><el-button v-else-if="page==='reports'" type="primary" :icon="Plus" @click="generate">生成报告</el-button><el-button v-else type="primary" :icon="Search" @click="run()">开始研究</el-button></div></div>
 <div v-if="!store.health.model_configured" class="notice"><span class="notice-dot"/>未配置模型 <span>产品管理与公开资料采集可用；AI 事实提取、变化分类和影响分析等待配置。</span><router-link to="/tasks">查看设置 →</router-link></div>
 <template v-if="page==='dashboard'">
 <div class="stats"><div v-for="[title,value,unit] in [['研究产品',dash.products,'个产品'],['公开数据源',dash.sources,'个来源'],['抓取成功率',dash.success_rate==null?'—':dash.success_rate+'%','最近一次采集状态'],['已检测变化',dash.changes,'条历史变化']]" class="stat"><span>{{title}}</span><strong>{{value??'—'}}</strong><small>{{unit}}</small></div></div>
 <div class="dashboard-grid"><section class="panel"><div class="section-heading"><h2>研究雷达 <span>PRODUCT LANDSCAPE</span></h2><router-link to="/products">管理产品 ↗</router-link></div><div class="product-radar" v-for="(p,index) in store.products.filter(p=>p.is_active)" :key="p.id" @click="router.push('/products/'+p.id)"><div class="product-mark" :class="'mark-'+index">{{p.name.slice(0,1)}}</div><div class="grow"><h3>{{p.name}}</h3><p>{{p.category}}</p></div><span class="pill">{{store.sources.filter(s=>s.product_id===p.id).length}} 个来源</span><el-icon><Right/></el-icon></div><el-empty v-if="!store.products.length" description="运行 seed 或添加第一个研究产品"/></section><section class="panel principle"><span class="eyebrow">THE RESEARCH STANDARD</span><div class="orb">✧</div><h2>先证据，后分析。</h2><p>不把演示当发布。<br>不把未知当缺失。<br>让每个判断回到原始来源。</p><div class="principle-bottom">EVIDENCE FIRST, ANALYSIS SECOND <span>↗</span></div></section></div>
 <section class="panel"><div class="section-heading"><h2>最近研究任务</h2><router-link to="/tasks">全部任务 →</router-link></div><el-table :data="dash.tasks||[]"><el-table-column prop="id" label="任务 ID" width="100"/><el-table-column label="状态"><template #default="{row}"><span class="pill">{{label(row.status)}}</span></template></el-table-column><el-table-column label="创建时间"><template #default="{row}">{{date(row.created_at)}}</template></el-table-column><el-table-column label="进度"><template #default="{row}"><el-progress :percentage="row.progress"/></template></el-table-column><template #empty>尚无研究任务，点击「开始研究」建立来源基线</template></el-table></section><el-alert v-for="e in dash.errors" :key="e.id" :title="e.url+' · '+e.error" type="error" :closable="false"/>
 </template>
 <template v-else-if="page==='products'"><div class="toolbar"><el-input v-model="query" :prefix-icon="Search" placeholder="搜索研究产品" style="max-width:300px"/><span>{{store.products.length}} 个产品 · 公开来源研究</span></div><div class="product-grid"><section class="panel product-card" v-for="p in visibleProducts" :key="p.id"><span class="pill">{{p.is_active?'研究中':'已停用'}}</span><h2><router-link :to="'/products/'+p.id">{{p.name}} ↗</router-link></h2><p>{{p.company}} / {{p.category}}</p><p>{{p.description||'等待补充产品介绍'}}</p><div class="card-footer"><el-button text @click="editProduct(p)">编辑</el-button><el-button text @click="addSource(p.id)">添加来源</el-button><el-button text type="danger" @click="disable(p)">停用</el-button></div></section></div><el-empty v-if="!visibleProducts.length" description="暂无产品"/><section class="panel"><div class="section-heading"><h2>数据源管理</h2><el-button :icon="Plus" @click="addSource()">添加来源</el-button></div><el-table :data="store.sources"><el-table-column label="产品" width="180"><template #default="{row}">{{names(row.product_id)}}</template></el-table-column><el-table-column prop="url" label="来源 URL" min-width="220" show-overflow-tooltip/><el-table-column prop="source_type" label="类型" width="160"/><el-table-column label="状态" width="130"><template #default="{row}">{{label(row.last_status)}}{{row.is_active?'':' / 已停用'}}</template></el-table-column><el-table-column label="操作" width="220"><template #default="{row}"><el-button link @click="editSource(row)">编辑</el-button><el-button link @click="toggleSource(row)">{{row.is_active?'停用':'启用'}}</el-button><el-button link :disabled="!row.is_active" @click="run(row.id)">采集</el-button><el-button link @click="showSnapshots(row)">快照</el-button></template></el-table-column></el-table><p v-for="s in store.sources.filter(s=>s.error)" :key="s.id" class="error-text">{{s.url}}：{{s.error}}</p></section></template>
 <template v-else-if="page==='detail'"><template v-if="product"><section class="panel"><div class="section-heading"><h2>{{product.company}} · {{product.category}}</h2><el-button @click="editProduct(product)">编辑产品</el-button></div><p>{{product.description||'尚无产品简介'}}</p><a :href="product.official_url" target="_blank" rel="noopener noreferrer">{{product.official_url}} ↗</a></section><section class="panel"><div class="section-heading"><h2>数据源与历史快照</h2><el-button @click="addSource(product.id)">添加来源</el-button></div><div class="source-row" v-for="s in detailSources" :key="s.id"><div class="grow"><a :href="s.url" target="_blank" rel="noopener noreferrer">{{s.url}}</a><p>{{label(s.last_status)}} · {{date(s.last_fetched_at)}} {{s.error}}</p></div><el-button @click="showSnapshots(s)">历史快照</el-button><el-button @click="run(s.id)">采集</el-button></div><el-empty v-if="!detailSources.length" description="尚无来源"/></section><section class="panel"><h2>结构化事实与证据</h2><div v-for="c in detailClaims" :key="c.id" class="claim" @click="showEvidence(c)"><span class="pill">{{c.dimension}}</span><h3>{{c.claim_text}}</h3><p>{{label(c.claim_status)}} / {{label(c.availability)}} / {{label(c.verification_status)}} <span class="link-text">查看证据 ↗</span></p></div><el-empty v-if="!detailClaims.length" description="尚无事实证据。采集来源并配置模型后执行研究。"/></section></template><el-empty v-else description="未找到产品"/></template>
 <template v-else-if="page==='comparison'"><div class="notice">未公开 ≠ 不支持。仅显示当前快照中原文验证通过的 Claim；产品关系由研究员审阅。</div><section class="panel"><div class="toolbar"><el-select v-model="selection" multiple placeholder="选择产品" style="min-width:300px"><el-option v-for="p in store.products" :key="p.id" :label="p.name" :value="p.id"/></el-select><el-select v-model="relation" style="width:170px"><el-option v-for="r in ['direct_competition','functional_overlap','ecosystem_benchmark','not_comparable','insufficient_evidence']" :key="r" :label="label(r)" :value="r"/></el-select><el-button @click="saveComparison" :disabled="selection.length<2">保存对比关系</el-button></div><div class="matrix-wrap"><table class="matrix"><thead><tr><th>能力维度</th><th v-for="pid in selection" :key="pid">{{names(pid)}}</th></tr></thead><tbody><tr v-for="dim in comparison.dimensions" :key="dim"><th>{{dim}}</th><td v-for="pid in selection" :key="pid"><div v-if="cell(pid,dim).length"><button class="matrix-claim" v-for="c in cell(pid,dim)" :key="c.id" @click="showEvidence(c)"><span class="pill">{{label(c.claim_status)}} · {{label(c.availability)}}</span><p>{{c.claim_text}}</p><span class="link-text">查看原始证据 ↗</span></button><el-tag v-if="new Set(cell(pid,dim).map((c:any)=>c.claim_status)).size>1" type="warning">来源状态不一致，需人工核验</el-tag></div><span v-else class="muted">未知 · 证据不足</span></td></tr></tbody></table></div><p v-for="c in comparison.saved" :key="c.id">已保存：{{c.product_ids.map(names).join(' / ')}} · {{label(c.relationship)}} · {{c.rationale}}</p></section></template>
 <template v-else-if="page==='timeline'"><el-empty v-if="!changes.length" description="建立基线完成后，等待下一次采集；没有历史变化时不生成时间线。"/><div v-for="c in changes" :key="c.id" class="timeline-item"><div class="timeline-date">{{date(c.created_at)}}</div><section class="panel"><div class="section-heading"><span class="pill">{{names(c.product_id)}} · {{label(c.change_type)}}</span><el-tag>{{label(c.importance)}}影响</el-tag></div><h2>{{c.title}}</h2><p>{{c.description}}</p><div class="diff-grid"><pre class="removed">− {{c.old_evidence||'（无旧证据）'}}</pre><pre class="added">+ {{c.new_evidence||'（无新证据）'}}</pre></div><a :href="c.source_url" target="_blank" rel="noopener noreferrer">原始来源 ↗</a><p class="muted">快照 {{c.old_snapshot_id}} → {{c.new_snapshot_id}} · {{label(c.verification_status)}}</p><div class="impact" v-for="i in impacts.filter(i=>i.change_event_id===c.id)" :key="i.id"><h3>对 {{names(i.target_product)}} 的潜在影响 · {{label(i.data.impact_level)}}</h3><p>模型推断：{{i.data.reasoning}}</p><p>关系：{{label(i.data.relationship)}} · 引用：{{i.data.evidence_claim_ids.join(', ')}}</p><p>机会：{{i.data.opportunities.join('；')}}</p><p>风险：{{i.data.risks.join('；')}}</p><p>产品建议：{{i.data.recommended_actions.join('；')}}</p><p>未知信息：{{i.data.uncertainties.join('；')}}</p></div></section></div></template>
 <template v-else-if="page==='reports'"><div class="reports-layout"><section class="panel"><h2>报告归档</h2><button class="report-item" v-for="r in reports" :key="r.id" @click="selectedReport=r"><el-icon><Document/></el-icon><strong>{{r.title}}</strong><small>{{date(r.created_at)}}</small></button><el-empty v-if="!reports.length" description="暂无报告"/></section><section class="panel report-preview"><template v-if="selectedReport"><div class="toolbar"><el-button @click="copy">复制 Markdown</el-button><el-button @click="download">下载 .md</el-button></div><article v-html="reportHtml"/></template><el-empty v-else description="选择报告，或从已保存证据生成新报告"/></section></div></template>
 <template v-else-if="page==='tasks'"><section class="panel"><h2>模型与环境设置</h2><el-descriptions :column="2" border><el-descriptions-item label="模型状态">{{store.health.model_configured?'已配置':'未配置模型'}}</el-descriptions-item><el-descriptions-item label="模型">{{store.health.model}}</el-descriptions-item><el-descriptions-item label="协议">{{store.health.protocol}}</el-descriptions-item><el-descriptions-item label="数据库">SQLite · 本地持久化</el-descriptions-item></el-descriptions><p class="muted">在项目根目录 .env 配置 OPENAI_API_KEY、OPENAI_BASE_URL、OPENAI_MODEL 和 LLM_PROTOCOL 后重启后端。密钥不会返回浏览器。仅供本地可信环境使用。</p><a href="http://127.0.0.1:8000/docs" target="_blank" rel="noopener noreferrer">打开 OpenAPI 文档 ↗</a></section><section class="panel" v-for="t in tasks" :key="t.id"><div class="section-heading"><h2>研究任务 #{{t.id}}</h2><span class="pill">{{label(t.status)}}</span></div><el-progress :percentage="t.progress"/><p>{{date(t.created_at)}} · {{t.usage.elapsed_seconds??'—'}} 秒 · {{t.usage.requests??0}} 次 API 请求 · {{t.usage.total_tokens??0}} tokens</p><div class="task-log" v-for="(log,i) in t.logs" :key="i">{{log.time?date(log.time):''}} {{log.source_id?'来源 #'+log.source_id:''}} {{log.message}}</div></section><el-empty v-if="!tasks.length" description="暂无任务记录"/></template>
 <el-dialog v-model="productDialog" :title="editing?'编辑产品':'添加产品'" width="min(560px,90vw)"><el-form label-position="top"><el-form-item v-for="(title,key) in {name:'产品名称',company:'公司',category:'分类',description:'产品介绍',official_url:'官方网站 URL'}" :key="key" :label="title"><el-input v-model="productForm[key]" :type="key==='description'?'textarea':'text'"/></el-form-item></el-form><template #footer><el-button @click="productDialog=false">取消</el-button><el-button type="primary" @click="saveProduct">保存</el-button></template></el-dialog>
 <el-dialog v-model="sourceDialog" :title="editing?'修改数据源':'添加公开数据源'" width="min(560px,90vw)"><el-form label-position="top"><el-form-item label="研究产品"><el-select v-model="sourceForm.product_id" :disabled="!!editing"><el-option v-for="p in store.products" :key="p.id" :value="p.id" :label="p.name"/></el-select></el-form-item><el-form-item label="公开来源 URL"><el-input v-model="sourceForm.url" placeholder="https://…"/></el-form-item><el-form-item label="类型"><el-select v-model="sourceForm.source_type"><el-option v-for="s in ['official_website','documentation','github_repository','release_notes','other']" :key="s" :label="s" :value="s"/></el-select></el-form-item></el-form><template #footer><el-button type="primary" @click="saveSource">保存来源</el-button></template></el-dialog>
 <el-drawer v-model="drawer" title="证据溯源" size="min(760px,95vw)"><template v-if="evidence"><span class="pill">{{label(evidence.verification_status)}} · {{label(evidence.availability)}}</span><h2>{{evidence.claim_text}}</h2><blockquote>{{evidence.evidence_text}}</blockquote><a :href="evidence.source_url" target="_blank" rel="noopener noreferrer">{{evidence.source_url}}</a><p>观察时间：{{date(evidence.observed_at)}} · 快照 #{{evidence.snapshot_id}}</p><p class="muted">原文匹配验证不等于对厂商声明的独立验证。</p></template><template v-if="snapshot"><template v-for="s in (Array.isArray(snapshot)?snapshot:[snapshot])" :key="s.id"><h3>快照 #{{s.id}} · {{date(s.created_at)}}</h3><small>{{s.content_hash}}</small><pre class="snapshot-text">{{s.content}}</pre></template></template><el-empty v-else description="尚无历史快照"/></el-drawer>
 </div>
</template>
